387	    const SerializationPtr & serialization,
388	    const NameAndTypePair & name_and_type,
389	    size_t from_mark,
390	    size_t current_task_last_mark,
391	    DeserializeBinaryBulkStateMap & deserialize_state_map,
392	    ISerialization::SubstreamsCache & cache,
393	    ISerialization::SubstreamsDeserializeStatesCache & deserialize_states_cache,
394	    ISerialization::StreamCallback prefixes_prefetch_callback)
395	{
396	    const auto & name = name_and_type.name;
397	    if (!deserialize_state_map.contains(name))
398	    {
399	        ISerialization::DeserializeBinaryBulkSettings deserialize_settings;
400	        deserialize_settings.object_and_dynamic_read_statistics = true;
401	        deserialize_settings.prefixes_prefetch_callback = prefixes_prefetch_callback;
402	        deserialize_settings.data_part_type = MergeTreeDataPartType::Wide;
403	        deserialize_settings.prefixes_deserialization_thread_pool = settings.use_prefixes_deserialization_thread_pool ? &getMergeTreePrefixesDeserializationThreadPool().get() : nullptr;
404	        deserialize_settings.getter = [&](const ISerialization::SubstreamPath & substream_path)
405	        {
406	            auto stream_name = IMergeTreeDataPart::getStreamNameForColumn(name_and_type, substream_path, ".bin", data_part_info_for_read->getChecksums(), storage_settings);
407	            /// This stream could be prefetched in prefetchBeginOfRange, but here we
408	            /// have to seek the stream to the start of file to deserialize the prefix.
409	            /// If we do not read from the first mark, we should remove this stream from
410	            /// prefetched_streams to prefetch it again starting from the current mark
411	            /// after prefix is deserialized.
412	            if (stream_name && from_mark != 0)
413	                prefetched_streams.erase(*stream_name);
414	
415	            return getStream(/* seek_to_start = */true, substream_path, data_part_info_for_read->getChecksums(), name_and_type, 0, /* seek_to_mark = */false, current_task_last_mark, cache);
416	        };
417	        /// Add streams for newly discovered dynamic subcolumns to start async marks loading beforehand if needed.
418	        deserialize_settings.dynamic_subcolumns_callback = [&](const ISerialization::SubstreamPath & substream_path)
419	        {
420	            /// Don't create streams for ephemeral subcolumns that don't store any real data.
421	            if (ISerialization::isEphemeralSubcolumn(substream_path, substream_path.size()))
422	                return;
423	
424	            auto stream_name = IMergeTreeDataPart::getStreamNameForColumn(name_and_type, substream_path, ".bin", data_part_info_for_read->getChecksums(), storage_settings);
425	            if (stream_name && !streams.contains(*stream_name))
426	                addStream(substream_path, *stream_name);
427	        };
428	        deserialize_settings.release_stream_callback = [&](const ISerialization::SubstreamPath & substream_path)
429	        {
430	            auto stream_name = IMergeTreeDataPart::getStreamNameForColumn(name_and_type, substream_path, ".bin", data_part_info_for_read->getChecksums(), storage_settings);
431	            if (stream_name)
432	                streams.erase(*stream_name);
433	        };
434	        deserialize_settings.release_all_prefixes_streams = settings.read_only_column_sample;
435	        deserialize_settings.has_uniform_marks_callback =
436	            [&](const ISerialization::SubstreamPath & substream_path,
437	                size_t max_transitions) -> bool
438	        {
439	            /// Wide parts with a final mark have a trailing position after the
440	            /// suffix, so a single per-part dictionary shows up as <= 2 distinct
441	            /// positions in the dictionary stream (data mark + final mark).
442	            /// Without a final mark, the same check must be stricter: a true
443	            /// single-dictionary part has only one distinct position, while a part
444	            /// with one dictionary in the main stream and another in the suffix can
445	            /// still look like "2 positions".
446	            const bool has_final_mark = data_part_info_for_read->getIndexGranularity().hasFinalMark();
447	            const size_t allowed_distinct_marks = has_final_mark || max_transitions == 0
448	                ? max_transitions
449	                : max_transitions - 1;
450	
451	            auto stream_name = IMergeTreeDataPart::getStreamNameForColumn(
452	                name_and_type, substream_path, ".bin",
453	                data_part_info_for_read->getChecksums(), storage_settings);
454	            if (!stream_name)
455	                return false;
456	
457	            auto it = streams.find(*stream_name);
458	            if (it == streams.end())
459	                return false;
460	
461	            return it->second->hasAtMostNDistinctMarks(allowed_distinct_marks);
462	        };
463	        serialization->deserializeBinaryBulkStatePrefix(deserialize_settings, deserialize_state_map[name], &deserialize_states_cache);
464	    }
